Tool schema:
{
  "name": "book_trip",
  "description": "Book a trip for a group of passengers. `traveller_contact.email` and `traveller_contact.phone` are alternatives: exactly one of them is required. `return_on` may not be before `depart_on`. `passengers` must have exactly `party_size` entries.",
  "parameters": {
    "type": "object",
    "properties": {
      "depart_on": {"type": "string", "format": "date", "description": "Day of departure."},
      "return_on": {"type": "string", "format": "date", "description": "Day of return."},
      "upgrade_code": {"type": "string", "description": "Code for a cabin upgrade."},
      "insurance": {"type": "boolean", "description": "Whether travel insurance is added."},
      "budget": {"type": "number", "minimum": 50, "maximum": 20000, "description": "Highest total price accepted."},
      "budget_currency": {"type": "string", "enum": ["EUR", "USD", "GBP"], "description": "Currency of budget."},
      "cost_centre": {"type": "string", "description": "Cost centre to charge."},
      "urgent": {"type": "boolean", "description": "Whether the request is urgent."},
      "language": {"type": "string", "enum": ["en", "de", "fr", "nl"], "description": "Language of the confirmation, as a two-letter ISO 639-1 code."},
      "traveller_contact": {
        "type": "object",
        "description": "Lead traveller of the group.",
        "required": ["name"],
        "additionalProperties": false,
        "properties": {
          "name": {"type": "string", "description": "Full name."},
          "email": {"type": "string", "description": "E-mail address."},
          "phone": {"type": "string", "description": "Phone number."}
        }
      },
      "passengers": {
        "type": "array",
        "description": "Passengers of the trip.",
        "minItems": 1,
        "maxItems": 6,
        "items": {
          "type": "object",
          "required": ["name", "age"],
          "additionalProperties": false,
          "properties": {
            "name": {"type": "string", "description": "Full name of the passenger."},
            "age": {"type": "integer", "minimum": 0, "maximum": 110, "description": "Age in years."},
            "seat": {"type": "string", "enum": ["window", "aisle", "any"], "description": "Seat preference."}
          }
        }
      },
      "party_size": {"type": "integer", "minimum": 0, "description": "Number of passengers."}
    },
    "required": ["depart_on", "return_on", "budget", "budget_currency", "language", "traveller_contact", "passengers", "party_size"],
    "additionalProperties": false
  }
}

