        }
      },
      "total_hours": {"type": "integer", "minimum": 0, "description": "Total number of hours of all shifts."}
    },
    "required": ["period_start", "period_end", "min_staff", "cost_centre", "language", "shifts", "total_hours"],
    "additionalProperties": false
  }
